sksl:
uniform shader image;
uniform shader palette;
uniform shader thresholds;
uniform float2 size;
uniform float time;
uniform float pattern;
uniform float dither;
uniform float pixel;
uniform float alpha;
uniform float paletteSize;
uniform float paletteSpread;
uniform half4 swatches[16];
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float3 lookup(float3 c) {
    c = clamp(c, 0.0, 1.0);
    if (paletteSize < 16.5) {
        float3 best = float3(0.0);
        float bestD = 100.0;
        for (int i = 0; i < 16; i++) {
            if (float(i) >= paletteSize) break;
            float3 s = float3(swatches[i].rgb);
            float d = dot(c - s, c - s);
            if (d < bestD) { bestD = d; best = s; }
        }
        return best;
    }
    float3 q = floor(c * 31.0 + 0.5);
    return float3(palette.eval(float2(mod(q.b, 8.0) * 32.0 + q.r + 0.5, floor(q.b / 8.0) * 32.0 + q.g + 0.5)).rgb);
}
half4 main(float2 coord) {
    float p = max(floor(pixel + 0.5), 1.0);
    float2 cell = floor(coord / p);
    half4 src = image.eval(coord);
    if (p > 1.5) {
        float2 o = cell * p;
        src = (image.eval(o + p * float2(0.25, 0.25)) + image.eval(o + p * float2(0.75, 0.25)) + image.eval(o + p * float2(0.25, 0.75)) + image.eval(o + p * float2(0.75, 0.75))) * 0.25;
    }
    if (src.a <= 0.0) return half4(0.0);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = base;
    if (pattern > 0.5 && pattern < 1.5) rgb += (hash12(cell) - 0.5) * dither * paletteSpread;
    else if (pattern > 1.5) rgb += (float(thresholds.eval(cell + 0.5).r) - 0.5) * dither * paletteSpread;
    return half4(half3(mix(base, lookup(rgb), clamp(alpha, 0.0, 1.0))) * src.a, src.a);
}
